def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = []
    op = []
    opp_c = 0
    my_d = 0
    same_d_c = 0
    opp_d_my_c = 0

    for a, b in history:
        me.append(a)
        op.append(b)
        if b == 'C':
            opp_c += 1
        if a == 'D':
            my_d += 1
        if a == 'D' and b == 'C':
            same_d_c += 1
        if a == 'C' and b == 'D':
            opp_d_my_c += 1

    opp_d = n - opp_c
    my_c = n - my_d
    opp_rate = opp_c / n
    last_me = me[-1]
    last_op = op[-1]
    prev_me = me[-2] if n >= 2 else 'C'

    recent_len = min(10, n)
    recent_d = 0
    for i in range(n - recent_len, n):
        if op[i] == 'D':
            recent_d += 1
    recent_c = recent_len - recent_d

    d_next_c = 0
    d_next_d = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                d_next_c += 1
            else:
                d_next_d += 1

    recent_start = max(0, n - 25)
    recent_d_next_c = 0
    recent_d_next_d = 0
    recent_same_d_c = 0
    recent_opp_d_my_c = 0
    recent_my_c = 0

    for i in range(recent_start, n):
        if me[i] == 'C':
            recent_my_c += 1
        if me[i] == 'D' and op[i] == 'C':
            recent_same_d_c += 1
        if me[i] == 'C' and op[i] == 'D':
            recent_opp_d_my_c += 1

    for i in range(recent_start, n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                recent_d_next_c += 1
            else:
                recent_d_next_d += 1

    defective = False

    # Clearly exploitative or mostly-defecting behavior: defect is best response.
    if opp_d * 2 >= n + 1:
        defective = True
    if my_c >= 8 and opp_d_my_c * 20 >= my_c * 7:
        defective = True
    if recent_my_c >= 6 and recent_opp_d_my_c * 20 >= recent_my_c * 7:
        defective = True
    if recent_len >= 6 and recent_d == recent_len and recent_opp_d_my_c >= recent_len - 2:
        defective = True
    if n >= 30 and opp_d * 100 >= n * 40 and recent_opp_d_my_c * 20 >= recent_my_c * 4:
        defective = True

    if defective:
        if n >= 95:
            return 'D'
        # Tiny chance to restore cooperation if there is strong recent mutual cooperation.
        if recent_c >= 6 and opp_rate > 0.6 and rng.random() < 0.03:
            return 'C'
        return 'D'

    exploitable = False

    # Opponent never defects: after a successful probe and one forgiving C, defect.
    if opp_d == 0 and my_d >= 1 and (d_next_c >= 1 or recent_same_d_c >= 2):
        exploitable = True

    # Recent behavior shows they cooperate after our D without immediate retaliation.
    elif recent_d_next_c >= 1 and recent_d_next_d == 0 and opp_rate >= 0.6:
        exploitable = True
    elif recent_d_next_c >= 2 and recent_d_next_c > 2 * recent_d_next_d and opp_rate >= 0.7:
        exploitable = True
    elif recent_same_d_c >= 2 and recent_d_next_d == 0 and opp_rate >= 0.75:
        exploitable = True

    # Exploit only when they are currently cooperating; if they fight back, use
    # the forgiving default below to recover and later reassess.
    if exploitable and last_op == 'C':
        if rng.random() < 0.88:
            return 'D'
        return 'C'

    # Default: nice, forgiving retaliator.
    # A short punishment followed by two cooperation rounds recovers against TFT-like
    # opponents after isolated or bounded defection bursts, without locking into DD.
    if last_op == 'D':
        if last_me == 'D':
            # Mutual defection: try to break the loop unless opponent is all D.
            if recent_d == recent_len:
                return 'D'
            return 'C'

        if prev_me == 'D':
            # Their D is likely a delayed response to our previous D; keep forgiving.
            if recent_d == recent_len:
                return 'D'
            return 'C'

        # They defected against our C: punish once.
        return 'D'

    # last_op == 'C'
    if last_me == 'D':
        # We just defected; wait one round to see whether they retaliate.
        # This prevents false exploitation of TFT while still allowing confirmation.
        return 'C'

    # Both cooperated last round.
    # Gentle one-time probe to distinguish pure cooperators from TFT/generous opponents.
    if opp_d == 0 and my_d == 0 and recent_c == recent_len and n >= 10 and n < 90:
        if rng.random() < 0.025:
            return 'D'
        if n >= 50 and rng.random() < 0.03:
            return 'D'

    return 'C'
